113	function showLoading(el, label = 'Loading…') {
114	    el.innerHTML = '';
115	    const wrapper = document.createElement('div');
116	    wrapper.className = 'loading-indicator';
117	    wrapper.setAttribute('aria-live', 'polite');
118	
119	    const spinner = document.createElement('span');
120	    spinner.className = 'spinner';
121	    spinner.setAttribute('aria-hidden', 'true');
122	    wrapper.appendChild(spinner);
123	
124	    const labelEl = document.createElement('span');
125	    labelEl.textContent = label;
126	    wrapper.appendChild(labelEl);
127	
128	    el.appendChild(wrapper);
