135	/**
136	 * Run workspace setup and show appropriate toast notification.
137	 *
138	 * @param {string} projectId
139	 * @param {string} workspaceId
140	 * @param {string} successMessage - Toast message shown when all repos succeed.
141	 * @returns {Promise<Object>} The setup result from the API.
142	 * @throws {Error} Re-throws API errors for the caller to handle.
143	 */
144	async function runSetup(projectId, workspaceId, successMessage) {
145	    const result = await api.workspaces.setup(projectId, workspaceId);
146	    const failures = (result && result.results || []).filter((r) => !r.success);
147	    if (failures.length > 0) {
148	        const names = failures.map((f) => f.repositoryId).join(', ');
149	        showToast(`Setup complete with errors. Failed to clone: ${names}`, 'warning', 8000);
150	    } else {
151	        showToast(successMessage, 'success');
152	    }
153	    return result;
154	}
