160	/**
161	 * Build a branch-switch trigger `<button>` styled as inline text.
162	 *
163	 * Extracted to avoid duplicating the element setup between `buildRepoStatusRow`
164	 * (initial render) and `updateStatusTable` (polling updates). The click handler
165	 * is wired by the caller so it can close over a fresh `trigger` reference.
166	 *
167	 * @param {string} branchName - Branch name shown as the button label.
168	 * @param {string} ariaLabel  - Accessible label for screen-readers.
169	 * @returns {HTMLButtonElement}
170	 */
171	function makeBranchTrigger(branchName, ariaLabel) {
172	    const btn = document.createElement('button');
173	    btn.type      = 'button';
174	    btn.className = 'branch-switch-trigger';
175	    btn.textContent = branchName;
176	    btn.setAttribute('aria-label', ariaLabel);
177	    return btn;
178	}
