205	function buildRepoStatusRow({ repoId, repoName, statusInfo, projectId, wid, isStable, onBranchCellClick, webserverUrl }) {
206	    const tr = document.createElement('tr');
207	    tr.dataset.repoId   = repoId;
208	    tr.dataset.repoName = repoName;
209	
210	    // Repository name / ID
211	    const nameCell = document.createElement('td');
212	    nameCell.className = 'repo-name-cell';
213	    const nameEl = document.createElement('span');
214	    nameEl.className = 'repo-name';
215	    nameEl.textContent = repoName;
216	    if (repoName !== repoId) {
217	        const idHint = document.createElement('span');
218	        idHint.className = 'text-muted repo-id-hint';
219	        idHint.textContent = ` (${repoId})`;
220	        nameEl.appendChild(idHint);
221	    }
222	    nameCell.appendChild(nameEl);
223	    tr.appendChild(nameCell);
224	
225	    // Branch name
226	    const branchCell = document.createElement('td');
227	    branchCell.className = 'repo-branch-cell';
228	    const currentBranch = (statusInfo && statusInfo.currentBranch) ? statusInfo.currentBranch : null;
229	    if (!isStable && currentBranch && onBranchCellClick) {
230	        const trigger = makeBranchTrigger(currentBranch, `Switch branch for ${repoName}`);
231	        trigger.addEventListener('click', () => onBranchCellClick(trigger, repoId, currentBranch));
232	        branchCell.appendChild(trigger);
233	    } else {
234	        branchCell.textContent = currentBranch || '—';
235	    }
236	    tr.appendChild(branchCell);
237	
238	    // Status badge cell (index 2 — must stay at this position)
239	    const badgeCell = document.createElement('td');
240	    badgeCell.className = 'repo-badge-cell';
241	
242	    const badgeWrapper = document.createElement('div');
243	    badgeWrapper.dataset.repoId = repoId;
244	    badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
245	    badgeCell.appendChild(badgeWrapper);
246	    tr.appendChild(badgeCell);
247	
248	    // Actions cell (index 3) — "Open" button for GitHub Desktop
249	    const actionsCell = document.createElement('td');
250	    actionsCell.className = 'repo-actions-cell';
251	
252	    const openBtn = document.createElement('button');
253	    openBtn.type      = 'button';
254	    openBtn.className = 'btn btn-secondary btn-sm';
255	    openBtn.textContent = 'Git GUI';
256	    openBtn.title = 'Open this repository in GitHub Desktop.';
257	
258	    openBtn.addEventListener('click', async () => {
259	        openBtn.disabled    = true;
260	        openBtn.textContent = 'Opening…';
261	        try {
262	            await api.workspaces.launch.githubDesktop(projectId, wid, repoId);
263	        } catch (err) {
264	            showToast(err.message || 'Failed to open GitHub Desktop.', 'error');
265	        } finally {
266	            openBtn.disabled    = false;
267	            openBtn.textContent = 'Git GUI';
268	        }
269	    });
270	
271	    actionsCell.appendChild(openBtn);
272	    tr.appendChild(actionsCell);
273	
274	    // Browse button — shown only when webserverUrl is configured.
275	    if (webserverUrl) {
276	        const browseBtn = document.createElement('button');
277	        browseBtn.type      = 'button';
278	        browseBtn.className = 'btn btn-secondary btn-sm';
279	        browseBtn.textContent = 'Browse';
280	        browseBtn.title = 'Open this repository in the browser via the configured webserver URL.';
281	
282	        browseBtn.addEventListener('click', () => {
283	            const url = `${webserverUrl}/${encodeURIComponent(projectId)}/${encodeURIComponent(wid)}/${encodeURIComponent(repoId)}/`;
284	            window.open(url, '_blank');
285	        });
286	
287	        // Insert Browse before Git GUI.
288	        actionsCell.insertBefore(browseBtn, openBtn);
289	    }
290	
291	    return tr;
292	}
