297	 *
298	 * Rows are located via `[data-repo-id]` on both the `<tr>` and the badge
299	 * wrapper `<div>` inside it. No full re-render of the table is performed.
300	 *

101	    badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
