154	/**
155	 * Update an existing repository row's branch and badge cells in-place.
156	 *
157	 * Cells are located by CSS class (`.repo-branch-cell`) and by the badge
158	 * wrapper's `data-repo-id` attribute — **not** by hardcoded cell indices —
159	 * so callers are free to add additional cells before or between the shared
160	 * cells without breaking this function.
161	 *
162	 * @param {HTMLTableRowElement} row          - The `<tr>` to update.
163	 * @param {string}              repoId       - Repository identifier (used to
164	 *                                             find the badge wrapper div).
165	 * @param {Object|null}         statusInfo   - New GitStatusInfo from the API,
166	 *                                             or `null` when no data is available.
167	 * @param {boolean}            [isStable]    - When `true`, the branch cell is
168	 *                                             rebuilt as plain text.
169	 * @param {function(HTMLElement, string, string): void} [onBranchCellClick]
170	 *                                             Wired to the branch trigger button
171	 *                                             in non-STABLE workspaces.
172	 *
173	 * @remarks
174	 * The aria-label for the branch trigger button is constructed as
175	 * `"Switch branch for <name>"` where `<name>` is `row.dataset.repoName`
176	 * when that attribute is present on the `<tr>`, falling back to `repoId`
177	 * when the attribute is absent or empty.
178	 */
179	export function updateRepoStatusCells(row, repoId, statusInfo, isStable, onBranchCellClick) {
180	    // Update branch cell — locate by class, not by index.
181	    const branchCell = row.querySelector('.repo-branch-cell');
182	    if (branchCell) {
183	        const currentBranch = (statusInfo && statusInfo.currentBranch) ? statusInfo.currentBranch : null;
184	        // Clear existing content before rebuilding (avoid innerHTML assignment).
185	        while (branchCell.firstChild) {
186	            branchCell.removeChild(branchCell.firstChild);
187	        }
188	        if (!isStable && currentBranch && onBranchCellClick) {
189	            const repoName = row.dataset.repoName || repoId;
190	            const trigger  = makeBranchTrigger(currentBranch, `Switch branch for ${repoName}`);
191	            trigger.addEventListener('click', () => onBranchCellClick(trigger, repoId, currentBranch));
192	            branchCell.appendChild(trigger);
193	        } else {
194	            branchCell.textContent = currentBranch || '—';
195	        }
196	    }
197	
198	    // Update badge wrapper — locate the <div data-repo-id="..."> inside the row.
199	    const badgeWrapper = row.querySelector(`div[data-repo-id="${CSS.escape(repoId)}"]`);
200	    if (badgeWrapper) {
201	        // Clear existing badge before replacing (avoid innerHTML assignment).
202	        while (badgeWrapper.firstChild) {
203	            badgeWrapper.removeChild(badgeWrapper.firstChild);
204	        }
205	        badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
206	    }
207	}

301	 * @param {HTMLElement}           tableBody - The `<tbody>` to update.
