318	                const repoName = row.dataset.repoName || repoId;
319	                const trigger = makeBranchTrigger(currentBranch, `Switch branch for ${repoName}`);
320	                trigger.addEventListener('click', () => onBranchCellClick(trigger, repoId, currentBranch));
321	                branchCell.appendChild(trigger);
322	            } else {
323	                branchCell.textContent = currentBranch || '—';
324	            }
325	        }
326	
327	        // Update badge wrapper (third cell → div[data-repo-id])
328	        const badgeWrapper = row.querySelector(`div[data-repo-id="${CSS.escape(repoId)}"]`);
329	        if (badgeWrapper) {
330	            badgeWrapper.innerHTML = '';
331	            badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
