340	/**
341	 * Build the rename workspace inline form and wire up its event handlers.
342	 *
343	 * @param {string} projectId
344	 * @param {{ id: string }} workspace
345	 * @param {HTMLButtonElement} renameBtn - The "Rename" button that toggles form visibility.
346	 * @returns {HTMLElement}
347	 */
348	function buildRenameForm(projectId, workspace, renameBtn) {
349	    const wrapper = document.createElement('div');
350	    wrapper.className = 'rename-workspace-form-wrapper card';
351	    wrapper.hidden = true;
352	
353	    const formTitle = document.createElement('h4');
354	    formTitle.className   = 'form-section-title';
355	    formTitle.textContent = 'Rename Workspace';
356	    wrapper.appendChild(formTitle);
357	
358	    const newIdField = createFormField('New Workspace ID', 'text', 'newWorkspaceId', {
359	        required:    true,
360	        placeholder: 'e.g. DEV or FEATURE',
361	        hint:        'Must be 2–10 uppercase letters (A-Z only).',
362	    });
363	    wrapper.appendChild(newIdField);
364	
365	    const newIdInput   = newIdField.querySelector('[name="newWorkspaceId"]');
366	    const newIdErrorEl = newIdField.querySelector('.field-error');
367	
368	    const formActions = document.createElement('div');
369	    formActions.className = 'form-actions';
370	
371	    const saveBtn = document.createElement('button');
372	    saveBtn.type      = 'button';
373	    saveBtn.className = 'btn btn-primary btn-sm';
374	    saveBtn.textContent = 'Save';
375	
376	    const cancelFormBtn = document.createElement('button');
377	    cancelFormBtn.type      = 'button';
378	    cancelFormBtn.className = 'btn btn-secondary btn-sm';
379	    cancelFormBtn.textContent = 'Cancel';
380	
381	    formActions.appendChild(saveBtn);
382	    formActions.appendChild(cancelFormBtn);
383	    wrapper.appendChild(formActions);
384	
385	    // Behaviour
386	    renameBtn.addEventListener('click', () => {
387	        wrapper.hidden = false;
388	        if (newIdInput) newIdInput.focus();
389	    });
390	
391	    cancelFormBtn.addEventListener('click', () => {
392	        wrapper.hidden = true;
393	        if (newIdInput) newIdInput.value = '';
394	        if (newIdErrorEl) newIdErrorEl.hidden = true;
395	    });
396	
397	    saveBtn.addEventListener('click', async () => {
398	        if (newIdErrorEl) newIdErrorEl.hidden = true;
399	        if (newIdInput) {
400	            newIdInput.classList.remove('error');
401	            newIdInput.removeAttribute('aria-invalid');
402	        }
403	
404	        if (!validateRequired(wrapper, ['newWorkspaceId'])) return;
405	
406	        const newId = newIdInput ? newIdInput.value.trim() : '';
407	
408	        if (!WORKSPACE_ID_PATTERN.test(newId)) {
409	            if (newIdErrorEl) {
410	                newIdErrorEl.textContent = 'Must be 2–10 uppercase letters (A-Z only).';
411	                newIdErrorEl.hidden      = false;
412	            }
413	            if (newIdInput) {
414	                newIdInput.classList.add('error');
415	                newIdInput.setAttribute('aria-invalid', 'true');
416	                newIdInput.focus();
417	            }
418	            return;
419	        }
420	
421	        try {
422	            await showConfirm(
423	                'Rename Workspace',
424	                `Rename workspace "${workspace.id}" to "${newId}"? The page will navigate to the new workspace URL.`,
425	            );
426	        } catch {
427	            return;
428	        }
429	
430	        saveBtn.disabled    = true;
431	        saveBtn.textContent = 'Saving…';
432	
433	        try {
434	            await api.workspaces.rename(projectId, workspace.id, newId);
435	            showToast(`Workspace renamed to "${newId}".`, 'success');
436	            const target = `#/projects/${encodeURIComponent(projectId)}/workspaces/${encodeURIComponent(newId)}`;
437	            if (_router) {
438	                _router.navigate(target);
439	            } else {
440	                location.hash = target;
441	            }
442	        } catch (err) {
443	            showToast(err.message || 'Failed to rename workspace.', 'error');
444	            saveBtn.disabled    = false;
445	            saveBtn.textContent = 'Save';
446	        }
447	    });
448	
449	    return wrapper;
450	}
