488	/**
489	 * Build the workspace header section — compact layout with breadcrumb,
490	 * workspace name, and a meta card for description + management actions.
491	 *
492	 * @param {string} projectId
493	 * @param {{ id: string, description: string, initialized: boolean, folderPath: string }} workspace
494	 * @param {boolean} isStable
495	 * @param {function(): void} [onSetupSuccess] - Called after a successful workspace setup, *after* the
496	 *   DOM mutation is complete (setupBtn removed from mgmtRow, vscodeBtn inserted before renameBtn,
497	 *   and `workspace.initialized` set to `true`). Intended to trigger a status refresh in the caller.
498	 * @returns {HTMLElement}
499	 */
500	function buildHeaderSection(projectId, workspace, isStable, onSetupSuccess) {

501	    const wrapper = document.createElement('div');
502	    wrapper.className = 'workspace-detail-header';
503	
504	    // Breadcrumb
505	    const breadcrumb = document.createElement('nav');
506	    breadcrumb.className = 'breadcrumb back-link text-muted';
