511	    projectLink.textContent = `← ${projectId}`;
512	    projectLink.className = 'breadcrumb-link';
513	    if (_router) {
514	        projectLink.addEventListener('click', (e) => {
515	            e.preventDefault();
516	            _router.navigate(`#/projects/${encodeURIComponent(projectId)}`);
517	        });
518	    }
519	    breadcrumb.appendChild(projectLink);
520	    wrapper.appendChild(breadcrumb);
521	
522	    // Title row: workspace ID
523	    const titleRow = document.createElement('div');
524	    titleRow.className = 'workspace-meta-top-row';
525	
526	    const titleEl = document.createElement('h1');
527	    titleEl.className   = 'project-meta-name';
528	    titleEl.textContent = workspace.id;
529	    titleRow.appendChild(titleEl);
530	
531	    // Description (inline, muted)
532	    if (workspace.description) {
533	        const descEl = document.createElement('span');
534	        descEl.className   = 'project-meta-id text-muted';
535	        descEl.textContent = workspace.description;
536	        titleRow.appendChild(descEl);
537	    }
