769	/**
770	 * Build a health alert section element from a workspace health report.
771	 * Returns `null` when the workspace is healthy (no issues to display).
772	 *
773	 * Fix-action buttons are wired via the `callbacks` argument so the
774	 * caller can inject async handlers that match the surrounding view's
775	 * closure state (project/workspace IDs, toast helper, etc.).
776	 *
777	 * @param {{ healthy: boolean, issues: Array<{ type: string, severity: string, message: string, fixAction: string, repositoryId?: string }> }|null} healthReport
778	 * @param {{ onRegenerate: function(): Promise<void>, onSetup: function(): Promise<void> }} callbacks
779	 * @returns {HTMLElement|null}
780	 */
781	function buildHealthAlertSection(healthReport, callbacks) {
782	    if (
783	        !healthReport ||
784	        healthReport.healthy ||
785	        !Array.isArray(healthReport.issues) ||
786	        healthReport.issues.length === 0
787	    ) {
788	        return null;
789	    }
790	
791	    const section = document.createElement('div');
792	    section.className = 'health-alert';
793	
794	    const title = document.createElement('div');
795	    title.className = 'health-alert-title';
796	    title.textContent = 'Workspace health issues detected';
797	    section.appendChild(title);
798	
799	    for (const issue of healthReport.issues) {
800	        const row = document.createElement('div');

 801	        row.className = 'health-alert-issue';
 802	
 803	        const msg = document.createElement('span');
 804	        msg.className = 'health-alert-issue__message';
 805	        msg.textContent = issue.message;
 806	        row.appendChild(msg);
 807	
 808	        if (issue.fixAction === 'regenerate-workspace-file') {
 809	            const actionWrap = document.createElement('span');
 810	            actionWrap.className = 'health-alert-issue__action';
 811	
 812	            const btn = document.createElement('button');
 813	            btn.type = 'button';
 814	            btn.className = 'btn btn-secondary btn-sm';
 815	            btn.textContent = 'Regenerate File';
 816	            btn.addEventListener('click', async () => {
 817	                btn.disabled = true;
 818	                btn.textContent = 'Regenerating\u2026';
 819	                try {
 820	                    await callbacks.onRegenerate();
 821	                } finally {
 822	                    btn.disabled = false;
 823	                    btn.textContent = 'Regenerate File';
 824	                }
 825	            });
 826	            actionWrap.appendChild(btn);
 827	            row.appendChild(actionWrap);
 828	        } else if (issue.fixAction === 'setup-workspace') {
 829	            const actionWrap = document.createElement('span');
 830	            actionWrap.className = 'health-alert-issue__action';
 831	
 832	            const btn = document.createElement('button');
 833	            btn.type = 'button';
 834	            btn.className = 'btn btn-secondary btn-sm';
 835	            btn.textContent = 'Fix Setup';
 836	            btn.addEventListener('click', async () => {
 837	                btn.disabled = true;
 838	                btn.textContent = 'Setting up\u2026';
 839	                try {
 840	                    await callbacks.onSetup();
 841	                } finally {
 842	                    btn.disabled = false;
 843	                    btn.textContent = 'Fix Setup';
 844	                }
 845	            });
 846	            actionWrap.appendChild(btn);
 847	            row.appendChild(actionWrap);
 848	        }
 849	        // Issues with an unknown fixAction render the message row without a button.
 850	
 851	        section.appendChild(row);
 852	    }
 853	
 854	    return section;
 855	}
