 861	/**
 862	 * Render the workspace detail view.
 863	 *
 864	 * Fetches workspace metadata, project (for the repositories list), polling
 865	 * configuration, and initial Git status in parallel. Then starts a polling
 866	 * interval that updates badges in-place using the server-configured interval
 867	 * (falls back to {@link DEFAULT_POLL_INTERVAL_MS} if the config fetch fails).
 868	 *
 869	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
 870	 * @param {{ id: string, wid: string }} params - Route parameters.
 871	 * @returns {function(): void} Cleanup function — clears the polling interval.
 872	 *   The router stores and calls this before rendering the next view.
 873	 */
 874	export function renderWorkspaceDetail(container, params) {
 875	    const projectId = params.id;
 876	    const wid       = params.wid;
 877	
 878	    let countdownInterval = null;
 879	
 880	    // Return the cleanup function immediately so the router can register it
 881	    // even if the async bootstrap hasn't resolved yet.
 882	    const cleanup = () => {
 883	        if (countdownInterval !== null) {
 884	            clearInterval(countdownInterval);
 885	            countdownInterval = null;
 886	        }
 887	    };
 888	
 889	    // Show loading state immediately.
 890	    showLoading(container, 'Loading workspace…');
 891	
 892	    // Kick off parallel data fetch.
 893	    Promise.all([
 894	        api.workspaces.get(projectId, wid),
 895	        api.projects.get(projectId),
 896	        api.status.refresh(projectId, wid).catch(() => null),
 897	        api.config.polling.get().catch(() => null),
 898	        api.workspaces.health(projectId, wid).catch(() => null),
 899	        api.config.webserverUrl.get().catch(() => null),
 900	    ]).then((results) => {
 901	        const [rawWorkspace, rawProject, statusMap, pollingConfig, healthReport, webserverUrlConfig] = results;
 902	        // Guard: if the container was cleared by navigation before we resolved,
 903	        // do nothing and let the cleanup function handle the interval.
 904	        if (!container.isConnected) return;
 905	
 906	        const workspace = normaliseWorkspace(rawWorkspace);
 907	        const project   = normaliseProject(rawProject);
 908	
 909	        // Build repo list: [{ repoId, repoName }, …]
 910	        const repos = project.repositories.map((r) => ({
 911	            repoId:   extractRepoId(r),
 912	            repoName: extractRepoName(r),
 913	        })).filter((r) => r.repoId !== '');
 914	
 915	        // Render the view.
 916	        container.innerHTML = '';
 917	
 918	        const isStable = wid === STABLE_WS_ID;
 919	
 920	        // Resolve the effective poll interval from server config, with fallback.
 921	        const pollIntervalMs = (
 922	            pollingConfig &&
 923	            typeof pollingConfig.gitPollingIntervalSeconds === 'number' &&
 924	            Number.isFinite(pollingConfig.gitPollingIntervalSeconds) &&
 925	            pollingConfig.gitPollingIntervalSeconds > 0
 926	        )
 927	            ? pollingConfig.gitPollingIntervalSeconds * 1000
 928	            : DEFAULT_POLL_INTERVAL_MS;
 929	
 930	        // Resolve webserver URL (null when not configured or fetch failed).
 931	        const webserverUrl = (
 932	            webserverUrlConfig &&
 933	            typeof webserverUrlConfig.webserverUrl === 'string' &&
 934	            webserverUrlConfig.webserverUrl !== ''
 935	        )
 936	            ? webserverUrlConfig.webserverUrl
 937	            : null;
 938	
 939	        // Build status table first to obtain tbody reference for helpers.
 940	        const { section: statusSection, tbody } = buildStatusTableSection(repos, statusMap || {}, projectId, wid, isStable, onBranchCellClick, webserverUrl);
 941	
 942	        // -------------------------------------------------------------------
 943	        // Refresh helpers (referenced by toolbar, polling, and setup)
 944	        // -------------------------------------------------------------------
 945	
 946	        let remainingSeconds = pollIntervalMs / 1000;
 947	        let refreshInProgress = false;
 948	
 949	        // Retry row reference — kept so polling can update/hide it.
 950	        let retryRow = null;
 951	        let retryHint = null;
 952	
 953	        // Toolbar elements — built now, wired after helpers are defined.
 954	        const toolbar = buildRefreshToolbar();
 955	        const progressBar = toolbar.querySelector('.refresh-progress-bar');
 956	        const refreshNowBtn = toolbar.querySelector('.refresh-now-btn');
 957	
 958	        // Health section container — always in DOM between header and toolbar;
 959	        // empty when the workspace is healthy.
 960	        const healthContainerEl = document.createElement('div');
 961	
 962	        // Latest health report — kept in sync by renderHealthSection so that
 963	        // updateMissingReposRow can exclude repos already covered by health alerts.
 964	        let currentHealthReport = healthReport;
 965	
 966	        /**
 967	         * Re-evaluate missing repos after a status update and hide/update
 968	         * the retry row accordingly.
 969	         *
 970	         * Repos flagged by a `repository-not-cloned` health alert (fixAction:
 971	         * `setup-workspace`) are excluded from the missing-repos count here
 972	         * because the health alert already surfaces a fix button for them.
 973	         * This row is therefore reserved for the transient polling-lag case
 974	         * where `.git/` is present but status data has not arrived yet.
 975	         */
 976	        function updateMissingReposRow(freshStatusMap) {
 977	            const notClonedIds = new Set(
 978	                (currentHealthReport && Array.isArray(currentHealthReport.issues)
 979	                    ? currentHealthReport.issues : [])
 980	                    .filter((i) => i.fixAction === 'setup-workspace' && i.repositoryId)
 981	                    .map((i) => i.repositoryId),
 982	            );
 983	            const currentMissing = repos.filter(
 984	                (r) => !freshStatusMap[r.repoId] && !notClonedIds.has(r.repoId),
 985	            );
 986	            if (currentMissing.length === 0) {
 987	                if (retryRow) {
 988	                    retryRow.remove();
 989	                    retryRow = null;
 990	                    retryHint = null;
 991	                }
 992	            } else if (retryHint) {
 993	                retryHint.textContent = `${currentMissing.length} ${currentMissing.length === 1 ? 'repository has' : 'repositories have'} no data \u2014 clone may have failed.`;
 994	            }
 995	        }
 996	
 997	        /**
 998	         * Rebuild the health alert container from the given health report.
 999	         * Updates `currentHealthReport` first so subsequent
1000	         * `updateMissingReposRow` calls reflect the latest health state.
1001	         *
1002	         * @param {{ healthy: boolean, issues: Array }|null} report
1003	         */
1004	        function renderHealthSection(report) {
1005	            currentHealthReport = report;
1006	            healthContainerEl.innerHTML = '';
1007	            const el = buildHealthAlertSection(report, {
1008	                onRegenerate: async () => {
1009	                    try {
1010	                        await api.workspaces.regenerateFile(projectId, wid);
1011	                        showToast('Workspace file regenerated.', 'success');
1012	                        await fetchAndRenderHealth();
1013	                    } catch (err) {
1014	                        showToast(err.message || 'Failed to regenerate workspace file.', 'error');
1015	                    }
1016	                },
1017	                onSetup: async () => {
1018	                    try {
1019	                        await runSetup(projectId, wid, 'Workspace setup complete.');
1020	                        doRefresh();
1021	                        await fetchAndRenderHealth();
1022	                    } catch (err) {
1023	                        showToast(err.message || 'Failed to set up workspace.', 'error');
1024	                    }
1025	                },
1026	            });
1027	            if (el) {
1028	                healthContainerEl.appendChild(el);
1029	            }
1030	        }
1031	
1032	        /**
1033	         * Fetch the latest health report from the API and re-render the
1034	         * health alert section in-place. Silently ignores network errors.
1035	         */
1036	        async function fetchAndRenderHealth() {
1037	            try {
1038	                const fresh = await api.workspaces.health(projectId, wid);
1039	                if (container.isConnected) {
1040	                    renderHealthSection(fresh);
1041	                }
1042	            } catch {
1043	                // Silently ignore health fetch errors — stale UI remains.
1044	            }
1045	        }
1046	
1047	        /**
1048	         * Automatic poll — uses cached status endpoint.
1049	         */
1050	        async function doPoll() {
1051	            if (refreshInProgress) return;
1052	            refreshInProgress = true;
1053	            try {
1054	                const [fresh, freshHealth] = await Promise.all([
1055	                    api.status.get(projectId, wid),
1056	                    api.workspaces.health(projectId, wid).catch(() => null),
1057	                ]);
1058	                if (container.isConnected) {
1059	                    renderHealthSection(freshHealth);
1060	                    if (fresh) {
1061	                        updateStatusTable(tbody, fresh, isStable, onBranchCellClick);
1062	                        updateMissingReposRow(fresh);
1063	                    }
1064	                }
1065	            } catch {
1066	                // Silently ignore polling errors — stale badges remain.
1067	            } finally {
1068	                refreshInProgress = false;
1069	                remainingSeconds = pollIntervalMs / 1000;
1070	                progressBar.classList.remove('refreshing');
1071	                progressBar.style.width = '0%';
1072	            }
1073	        }
1074	
1075	        /**
1076	         * Manual force-refresh — calls the live git-fetch endpoint.
1077	         */
1078	        async function doRefresh() {
1079	            if (refreshInProgress) return;
1080	            refreshInProgress = true;
1081	            refreshNowBtn.disabled = true;
1082	            progressBar.classList.add('refreshing');
1083	            try {
1084	                const [fresh, freshHealth] = await Promise.all([
1085	                    api.status.refresh(projectId, wid),
1086	                    api.workspaces.health(projectId, wid).catch(() => null),
1087	                ]);
1088	                if (container.isConnected) {
1089	                    renderHealthSection(freshHealth);
1090	                    if (fresh) {
1091	                        updateStatusTable(tbody, fresh, isStable, onBranchCellClick);
1092	                        updateMissingReposRow(fresh);
1093	                    }
1094	                }
1095	            } catch {
1096	                // Silently ignore — stale badges remain.
1097	            } finally {
1098	                refreshInProgress = false;
1099	                refreshNowBtn.disabled = false;
1100	                remainingSeconds = pollIntervalMs / 1000;

1101	                progressBar.classList.remove('refreshing');
1102	                progressBar.style.width = '0%';
1103	            }
1104	        }
1105	
1106	        /**
1107	         * Start the 1-second countdown interval.
1108	         */
1109	        function startCountdown() {
1110	            if (countdownInterval) return;
1111	            countdownInterval = setInterval(() => {
1112	                if (!container.isConnected) {
1113	                    cleanup();
1114	                    return;
1115	                }
1116	                remainingSeconds--;
1117	                if (remainingSeconds <= 0) {
1118	                    progressBar.classList.add('refreshing');
1119	                    doPoll();
1120	                } else {
1121	                    const totalSeconds = pollIntervalMs / 1000;
1122	                    const pct = ((totalSeconds - remainingSeconds) / totalSeconds) * 100;
1123	                    progressBar.style.width = `${pct}%`;
1124	                }
1125	            }, 1000);
1126	        }
1127	
1128	        refreshNowBtn.addEventListener('click', doRefresh);
1129	
1130	        /**
1131	         * Handle a click on a branch cell trigger in the status table.
1132	         *
1133	         * Dynamically imports the branch-quick-switch component (avoiding
1134	         * loading it in STABLE workspaces or on initial page load), shows the
1135	         * popover anchored below `anchorEl`, then triggers a status refresh on
1136	         * a successful switch.
1137	         *
1138	         * @param {HTMLElement} anchorEl      - The clicked trigger button.
1139	         * @param {string}      repoId        - Repository ID to switch.
1140	         * @param {string}      currentBranch - Currently checked-out branch name.
1141	         */
1142	        function onBranchCellClick(anchorEl, repoId, currentBranch) {
1143	            import('../components/branch-quick-switch.js')
1144	                .then(({ showBranchQuickSwitch }) =>
1145	                    showBranchQuickSwitch({ anchorEl, projectId, wid, repoId, currentBranch }),
1146	                )
1147	                .then((result) => { if (result.switched) doRefresh(); })
1148	                .catch(() => { showToast('Failed to load branch switcher.', 'error'); });
